  "java/generated/rag/DocumentController.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.rag;\n\n<%- imports %>\n\n/** For the agent-admin role: the documents of the knowledge base, beside those of the documents folder. */\n@<%= type('org.springframework.web.bind.annotation.RestController') %>\n@<%= type('org.springframework.web.bind.annotation.RequestMapping') %>(\"/api/admin/documents\")\nclass DocumentController {\n\n    /** Where uploaded documents are kept, apart from the files of the documents folder. */\n    static final String UPLOADS = \"upload/\";\n\n    private final KnowledgeBase knowledgeBase;\n\n    DocumentController(KnowledgeBase knowledgeBase) {\n        this.knowledgeBase = knowledgeBase;\n    }\n\n    @<%= type('org.springframework.web.bind.annotation.GetMapping') %>\n    <%= type('java.util.List') %><IndexedDocument> documents() {\n        return knowledgeBase.documents();\n    }\n\n    /** Indexes the file, in place of an earlier upload of the same name. */\n    @<%= type('org.springframework.web.bind.annotation.PostMapping') %>\n    <%= type('org.springframework.http.ResponseEntity') %><IndexedDocument> upload(@<%= type('org.springframework.web.bind.annotation.RequestParam') %> <%= type('org.springframework.web.multipart.MultipartFile') %> file) throws <%= type('java.io.IOException') %> {\n        String name = <%= type('org.springframework.util.StringUtils') %>.getFilename(file.getOriginalFilename());\n        if (name == null || name.isBlank()) {\n            return ResponseEntity.badRequest().build();\n        }\n        String source = UPLOADS + name;\n        knowledgeBase.index(source, file.getResource());\n        return ResponseEntity.status(<%= type('org.springframework.http.HttpStatus') %>.CREATED)\n                .body(knowledgeBase.documents().stream().filter(document -> document.source().equals(source)).findFirst().orElseThrow());\n    }\n\n    @<%= type('org.springframework.web.bind.annotation.DeleteMapping') %>\n    ResponseEntity<Void> forget(@RequestParam String source) {\n        return knowledgeBase.forget(source) ? ResponseEntity.noContent().build() : ResponseEntity.notFound().build();\n    }\n}\n",
