  "java/generated/rag/DocumentStoreConfiguration.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.rag;\n\n<%- imports %>\n\n@<%= type('org.springframework.context.annotation.Configuration') %>(proxyBeanMethods = false)\nclass DocumentStoreConfiguration {\n\n    /** Its own table, agent_document: the passages of the documents, compared by cosine distance. */\n    @<%= type('org.springframework.context.annotation.Bean') %>\n    <%= type('org.springframework.ai.vectorstore.pgvector.PgVectorStore') %> documentStore(\n            <%= type('org.springframework.jdbc.core.JdbcTemplate') %> jdbcTemplate, <%= type('org.springframework.ai.embedding.EmbeddingModel') %> embeddingModel, <%= type(`${project.generatedPackage}.AgentProperties`) %> properties) {\n        return PgVectorStore.builder(jdbcTemplate, embeddingModel)\n                .vectorTableName(\"agent_document\")\n                .dimensions(properties.rag().dimensions())\n                .distanceType(PgVectorStore.PgDistanceType.COSINE_DISTANCE)\n                .indexType(PgVectorStore.PgIndexType.HNSW)\n                .initializeSchema(true)\n                .build();\n    }\n}\n",
