  "java/generated/ui/ChatUiController.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.ui;\n\n<%- imports %>\n\n/** Settings of the chat page (src/main/resources/static), read by chat.js: public, they hold no secret. */\n@<%= type('org.springframework.web.bind.annotation.RestController') %>\nclass ChatUiController {\n\n    private final ChatUiSettings settings;\n\n<%_ if (features.oidc) { _%>\n    ChatUiController(\n            @<%= type('org.springframework.beans.factory.annotation.Value') %>(\"${spring.security.oauth2.resourceserver.jwt.issuer-uri}\") String issuer,\n            @Value(\"${agent.chat-ui.client-id}\") String clientId) {\n        this.settings = new ChatUiSettings(\"oidc\", issuer, clientId, <%= features.feedback %>);\n    }\n<%_ } else { _%>\n    ChatUiController() {\n        this.settings = new ChatUiSettings(\"none\", null, null, <%= features.feedback %>);\n    }\n<%_ } _%>\n\n    @<%= type('org.springframework.web.bind.annotation.GetMapping') %>(\"/chat-config.json\")\n    ChatUiSettings settings() {\n        return settings;\n    }\n\n    /**\n     * @param auth how users sign in: oidc, or none\n     * @param issuer the OIDC provider the page signs users in with\n     * @param clientId the public client of the page at that provider\n     * @param feedback whether the page shows thumbs up and down under the answers\n     */\n    record ChatUiSettings(String auth, String issuer, String clientId, boolean feedback) {}\n}\n",
  "java/tool/DefaultToolHandler.java.ejs": "package <%= project.basePackage %>.tool;\n\n<%- imports %>\n\n@<%= type('org.springframework.stereotype.Component') %>\nclass <%= item.handlerClass %> implements <%= type(`${project.generatedPackage}.tool.${item.handlerInterface}`) %> {\n\n    @Override\n    public String <%= item.methodName %>(<%= item.params.map((param) => `${param.javaType} ${param.name}`).join(', ') %>) {\n        // Implement <%= item.name %> here: the text you return is what the model reads.\n        throw new UnsupportedOperationException(\"<%= item.name %> is not implemented yet\");\n    }\n}\n",
