  "test/generated/tool/LoggedToolCallbackTests.java.ejs": "// Managed by gen-agent: changes here are overwritten.\npackage <%= project.generatedPackage %>.tool;\n\n<%- imports %>\n\n@<%= type('org.junit.jupiter.api.extension.ExtendWith') %>(<%= type('org.springframework.boot.test.system.OutputCaptureExtension') %>.class)\nclass LoggedToolCallbackTests {\n\n    @<%= type('org.junit.jupiter.api.Test') %>\n    void logsTheToolAndItsDurationNeverItsArgumentsNorItsResult(<%= type('org.springframework.boot.test.system.CapturedOutput') %> output) {\n        <%= type('org.springframework.ai.tool.ToolCallback') %> tool = LoggedToolCallback.logged(new ToolCallback[] {tool(\"transfer\", input -> \"sent to \" + input)})[0];\n\n        <%= staticImport('org.assertj.core.api.Assertions.assertThat') %>(tool.call(\"FR7630006000011234567890189\")).isEqualTo(\"sent to FR7630006000011234567890189\");\n        assertThat(output).contains(\"Tool transfer answered in\").doesNotContain(\"FR7630006000011234567890189\");\n    }\n\n    @Test\n    void logsAFailureAndLetsItThrough(CapturedOutput output) {\n        ToolCallback tool = LoggedToolCallback.logged(new ToolCallback[] {tool(\"transfer\", input -> {\n            throw new <%= type('java.lang.IllegalStateException') %>(\"bank down for FR7630006000011234567890189\");\n        })})[0];\n\n        <%= staticImport('org.assertj.core.api.Assertions.assertThatThrownBy') %>(() -> tool.call(\"{}\")).isInstanceOf(IllegalStateException.class);\n        assertThat(output).contains(\"Tool transfer failed after\", \"IllegalStateException\").doesNotContain(\"FR7630006000011234567890189\");\n    }\n\n    private static ToolCallback tool(String name, <%= type('java.util.function.UnaryOperator') %><String> behaviour) {\n        return new ToolCallback() {\n            @Override\n            public <%= type('org.springframework.ai.tool.definition.ToolDefinition') %> getToolDefinition() {\n                return ToolDefinition.builder().name(name).description(name).inputSchema(\"{}\").build();\n            }\n\n            @Override\n            public String call(String toolInput) {\n                return behaviour.apply(toolInput);\n            }\n        };\n    }\n}\n",
